INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES (692, 302, 151, 'IP Paris PhD Track Excellence Scholarships', 'available', 'Full Funding', 'Full Package: Master''s excellence scholarship €10,000/year (2 years) + 3-year doctoral funding commitment (approx. €82,800 minimum gross over 3 years); Master''s-only and Doctoral-only packages also awarded', true, true, 'Excellence judged by a jury after admission (automatic)', 'Five-year English-taught PhD Track (Master''s + PhD) across 12 tracks; Bachelor''s 180 ECTS entry (Year-2 entry possible at 240 ECTS/Master''s). No separate scholarship application - a jury reviews admitted files and IP Paris notifies awardees (funding waiting list otherwise). Tuition subsidised for all admitted students to €243/year (Years 1-2) and €380/year (Years 3-5). 2027-28 applications 28 Oct 2026 - 14 Jan 2027.', 'https://www.ip-paris.fr/en/education/graduate-programs/phd-track', 'https://www.ip-paris.fr/en/education/useful-information/scholarships', 'verified', now());
SELECT setval('university_scholarships_id_seq', (SELECT max(id) FROM university_scholarships));
